export function localizeYearPremiumPages(
  source: string,
  locale: PaidPdfLocale,
): string {
  if (locale === "fr") {
    return source;
  }

  let output = source;

  const ordered =
    [...YEAR_PREMIUM_SECTION_A_TRANSLATIONS]
      .sort(
        (a, b) =>
          b.from.length -
          a.from.length,
      );

  for (const entry of ordered) {
    output =
      output
        .split(entry.from)
        .join(entry.to[locale]);
  }

  return output;
}
